program NutFile;
var
  F: Text;
  Line: string;
  SpacePos, N, Code, Total: Integer;
  Name: string;
begin
  Assign(F, 'nuts.txt');
  Rewrite(F);
  WriteLn(F, 'acorn 12');
  WriteLn(F, 'walnut 5');
  WriteLn(F, 'hazel 9');
  Close(F);
  Assign(F, 'nuts.txt');
  Reset(F);
  Total := 0;
  while not Eof(F) do
  begin
    ReadLn(F, Line);
    SpacePos := Pos(' ', Line);
    Name := Copy(Line, 1, SpacePos - 1);
    Val(Copy(Line, SpacePos + 1, 255), N, Code);
    WriteLn(Name, ' => ', N);
    Total := Total + N;
  end;
  Close(F);
  WriteLn('total ', Total);
end.

