program Ptrs;
type
  PNode = ^TNode;
  TNode = record
    Nuts: Integer;
    Next: PNode;
  end;
var
  Head, P: PNode;
  Sum: Integer;
begin
  New(Head);
  Head^.Nuts := 3;
  New(Head^.Next);
  Head^.Next^.Nuts := 5;
  New(Head^.Next^.Next);
  Head^.Next^.Next^.Nuts := 7;
  Head^.Next^.Next^.Next := nil;
  Sum := 0;
  P := Head;
  while P <> nil do
  begin
    WriteLn(P^.Nuts);
    Sum := Sum + P^.Nuts;
    P := P^.Next;
  end;
  WriteLn('sum ', Sum);
  Dispose(Head^.Next^.Next);
  Dispose(Head^.Next);
  Dispose(Head);
end.

